class Solution { fun differenceOfDistinctValues(grid:Array<IntArray>):Array<IntArray>{val rows=grid.size;val cols=grid[0].size;val answer=Array(rows){IntArray(cols)};for(row in 0 until rows)for(col in 0 until cols){val topLeft=HashSet<Int>();val bottomRight=HashSet<Int>();var r=row-1;var c=col-1;while(r>=0&&c>=0){topLeft.add(grid[r][c]);r--;c--};r=row+1;c=col+1;while(r<rows&&c<cols){bottomRight.add(grid[r][c]);r++;c++};answer[row][col]=kotlin.math.abs(topLeft.size-bottomRight.size)};return answer} }
